 U0 *host; Random *random; Bool isClient,goodGraphics; I32 obsidianID,redstoneID,redstoneOreID,redstoneOreLitID,snowballID,signItemID,grassID,dirtID,sandID,leavesID,trunkID,fenceGateID,roseID,flowerID,redReactorID,goldID,stoneID,reactorID,shearsID,seedsID,reedsID,deadBushID,tallgrassID;
 I32 (*getTile)(U0 *,I32,I32,I32); I32 (*getData)(U0 *,I32,I32,I32); Bool (*empty)(U0 *,I32,I32,I32); Bool (*solid)(U0 *,I32,I32,I32); Bool (*water)(U0 *,I32,I32,I32); Bool (*baseMayPlace)(U0 *,I32,I32,I32); Bool (*baseRenderFace)(U0 *,I32,I32,I32,I32); Bool (*solidBlockingID)(U0 *,I32); Bool (*cubeID)(U0 *,I32); Bool (*vegetableID)(U0 *,I32); Bool (*hasChunks)(U0 *,I32,I32,I32,I32,I32,I32); I32 (*brightness)(U0 *,I32,I32,I32); Bool (*survive)(U0 *,I32,I32,I32,I32); Bool (*placeFeature)(U0 *,I32,Random *,I32,I32,I32);
 U0 (*setTile)(U0 *,I32,I32,I32,I32,I32); U0 (*setTileData)(U0 *,I32,I32,I32,I32,I32,I32); U0 (*setTileNoUpdate)(U0 *,I32,I32,I32,I32); U0 (*setTileDataNoUpdate)(U0 *,I32,I32,I32,I32,I32); U0 (*setDataNoUpdate)(U0 *,I32,I32,I32,I32); U0 (*setData)(U0 *,I32,I32,I32,I32,I32); U0 (*removeTile)(U0 *,I32,I32,I32); U0 (*spawnResources)(U0 *,I32,I32,I32,I32,F32); U0 (*popItem)(U0 *,I32,I32,I32,I32,I32); U0 (*addRedDust)(U0 *,F32,F32,F32); Bool (*baseUse)(U0 *,I32,I32,I32,U0 *); U0 (*baseNeighbor)(U0 *,I32,I32,I32,I32,I32,I32,I32); Bool (*solidRenderID)(U0 *,I32); Bool (*blocksMotion)(U0 *,I32,I32,I32); I32 (*blockBrightness)(U0 *,I32,I32,I32); U0 (*spawnSnowball)(U0 *,F32,F32,F32,I32,I32); U0 (*basePlayerDestroy)(U0 *,I32,I32,I32,I32); U0 (*checkAlive)(U0 *,I32,I32,I32); TextureUVCoordinateSet *(*texture)(U0 *,U8 *,I32); TextureUVCoordinateSet *(*clothTexture)(U0 *,I32,I32); TextureUVCoordinateSet *(*wallTexture)(U0 *,Bool,I32); I32 (*grassColorData)(U0 *,I32); I32 (*grassColorAt)(U0 *,I32,I32,I32);
