Bool MC013_connects(MCTileHost013 *h,I32 self,I32 x,I32 y,I32 z){I32 id=h->getTile(h->host,x,y,z);if(id==self || id==h->fenceGateID)return TRUE;return h->solidBlockingID(h->host,id) && h->cubeID(h->host,id) && !h->vegetableID(h->host,id);}
U0 MC013_poofParticles(MCTileHost013 *h,I32 x,I32 y,I32 z){I32 i;F32 px,py,pz;for(i=0;i<6;i++){px=x+Random_nextFloat(h->random);py=y+Random_nextFloat(h->random);pz=z+Random_nextFloat(h->random);if(i==0){if(!h->solid(h->host,x,y+1,z))py=y+1+0.0625;}else if(i==1){if(!h->solid(h->host,x,y-1,z))py=y-0.0625;}else if(i==2){if(!h->solid(h->host,x,y,z+1))pz=z+1+0.0625;}else if(i==3){if(!h->solid(h->host,x,y,z-1))pz=z-0.0625;}else if(i==4){if(!h->solid(h->host,x+1,y,z))px=x+1+0.0625;}else if(!h->solid(h->host,x-1,y,z))px=x-0.0625;if(px<x||px>x+1||py<0||py>y+1||pz<z||pz>z+1)h->addRedDust(h->host,px,py,pz);}}
