U0 MC013_appendC(MCString *s,U8 *p){I64 n=MC_StrLen(p);U8 *v=MC_Alloc(s->size+n+1);if(s->size)memcpy(v,s->data,s->size);if(n)memcpy(v+s->size,p,n);v[s->size+n]=0;free(s->data);s->data=v;s->size+=n;}
